// go: github.com/microsoft/TypeScript/tsc/internal/ls.LanguageService.getJSDocSnippetCompletion cdc2d0aa
fun LanguageService?.getJSDocSnippetCompletion(ctx: Context?, file: SourceFile?, position: Int): CompletionList? {
    if (this.userPreferences().completeJSDocs.isFalse()) {
        return null
    }
    if (!isPotentiallyValidJSDocSnippetCompletionPosition(file, position)) {
        return null
    }
    var newLine: String = this.formatOptions().editorSettings.newLineCharacter
    if (newLine == "") {
        newLine = "\n"
    }
    val template: com.xemantic.typescript.tsgo.ls.docCommentTemplate? = getDocCommentTemplateAtPosition(file, position, this.userPreferences().generateReturnInDocTemplate.isTrue(), newLine)
    if (template == null) {
        return null
    }
    var insertText: String = template!!.newText
    var insertTextFormat: GoPtr<InsertTextFormat>? = null
    if (clientSupportsItemSnippet(ctx)) {
        insertText = templateToSnippet(insertText, newLine)
        insertTextFormat = GoBox<InsertTextFormat>(InsertTextFormat(2u))
    }
    val editRange: TextEditOrInsertReplaceEdit? = this.getJSDocSnippetCompletionRange(ctx, file, position, insertText)
    var commitCharacters: GoPtr<GoSlice<String>>? = null
    if (clientSupportsItemCommitCharacters(ctx)) {
        commitCharacters = GoBox(GoSlice.make(GoElem.STRING, 0))
    }
    val item: CompletionItem? = CompletionItem(completionItem = com.xemantic.typescript.tsgo.lsp.lsproto.CompletionItem(label = "/** */", kind = GoBox<CompletionItemKind>(CompletionItemKind(1u)), detail = GoBox<String>(com.xemantic.typescript.tsgo.diagnostics.jsDoc_comment.localize(com.xemantic.typescript.tsgo.locale.fromContext(ctx), GoElem.ref<Any?>().nilSlice)), sortText = GoBox<String>("\u0000"), insertTextFormat = insertTextFormat, textEdit = editRange, commitCharacters = commitCharacters))
    return CompletionList(isIncomplete = false, items = GoSlice.of(GoElem.ref<CompletionItem?>(), item))
}

// go: github.com/microsoft/TypeScript/tsc/internal/ls.isPotentiallyValidJSDocSnippetCompletionPosition 2b6b48bf
fun isPotentiallyValidJSDocSnippetCompletionPosition(file: SourceFile?, position: Int): Boolean {
    val text: String = file!!.text()
    val lineStart: Int = com.xemantic.typescript.tsgo.format.getLineStartPositionForPosition(position, file)
    val prefix: String = text.substring(lineStart, position)
    if (!isJSDocSnippetPrefix(prefix)) {
        return false
    }
